package dev.zomboid.installer;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.function.*;import java.util.regex.*;import java.util.zip.*;
public final class Engine {
 public record Entry(String path,String sha256,long size){}
 public record Pack(Path root,String name,String mode,String minecraft,String neoForge,List<Entry> files,Map<String,String> options,List<String> requiredMods){}
 public record Check(String group,String title,String detail,boolean good){}
 public record Copy(Path source,String relative,String sha){}
 public record Plan(Path instance,Pack pack,List<Check> checks,List<Copy> copies,List<String> obsolete,String fingerprint){public boolean allowed(){return checks.stream().allMatch(Check::good);}}
 private static final Set<String> ROOTS=Set.of("mods","config","resourcepacks","shaderpacks","datapacks");
 private static String str(Object o){return Objects.toString(o,"");}
 public static String sha(Path p)throws IOException {try{MessageDigest m=MessageDigest.getInstance("SHA-256");try(InputStream in=Files.newInputStream(p)){byte[] b=new byte[65536];int n;while((n=in.read(b))>=0)m.update(b,0,n);}return HexFormat.of().formatHex(m.digest());}catch(NoSuchAlgorithmException e){throw new AssertionError(e);}}
 public static String safeName(String input)throws IOException {String s=input.replace('\\','/');if(s.startsWith("/")||s.contains(":")||s.contains("\0"))throw new IOException("Ruta no válida: "+s);String[] parts=s.split("/",-1);for(String part:parts)if(part.isEmpty()||part.equals(".")||part.equals(".."))throw new IOException("Ruta no válida: "+s);return s;}
 private static Path under(Path root,String relative)throws IOException {relative=safeName(relative);Path base=root.toAbsolutePath().normalize(),dest=base.resolve(relative).normalize();if(!dest.startsWith(base))throw new IOException("Ruta fuera de la instancia");Path real=Files.exists(base)?base.toRealPath():base;for(Path p=dest;p!=null&&p.startsWith(base);p=p.getParent()){if(Files.isSymbolicLink(p))throw new IOException("Enlace no permitido: "+p);if(Files.exists(p)&&!p.toRealPath().startsWith(real))throw new IOException("Ruta redirigida fuera de instancia");}return dest;}
 private static boolean managed(String path){int slash=path.indexOf('/');return slash>0&&ROOTS.contains(path.substring(0,slash));}
 public static Pack load(Path root)throws IOException {Path manifest=root.resolve("pack.json");if(!Files.isRegularFile(manifest))throw new IOException("No se encontró pack.json. Importa un ZIP completo o exporta una instancia.");Map<String,Object> m=Json.object(Json.parse(Files.readString(manifest)));if(((Number)m.getOrDefault("formatVersion",0)).intValue()!=1)throw new IOException("Formato de pack no compatible");List<Entry> files=new ArrayList<>();Set<String> seen=new HashSet<>();for(Object x:Json.list(m.get("files"))){Map<String,Object> f=Json.object(x);String path=safeName(str(f.get("path")));if(!managed(path)||!seen.add(path.toLowerCase(Locale.ROOT)))throw new IOException("Archivo duplicado o no permitido: "+path);String hash=str(f.get("sha256"));long size=((Number)f.get("size")).longValue();if(!hash.matches("[a-f0-9]{64}")||size<0)throw new IOException("Firma no válida: "+path);files.add(new Entry(path,hash,size));}Map<String,String> options=new LinkedHashMap<>();Json.object(m.getOrDefault("options",Map.of())).forEach((k,v)->{if(k.startsWith("key_")||Set.of("guiScale","resourcePacks","incompatibleResourcePacks").contains(k))options.put(k,str(v));});List<String> required=Json.list(m.getOrDefault("requiredModIds",List.of())).stream().map(Engine::str).toList();return new Pack(root.toAbsolutePath(),str(m.get("name")),str(m.getOrDefault("mode","full")),str(m.get("minecraft")),str(m.get("neoForge")),List.copyOf(files),Map.copyOf(options),required);}
 public static Map<String,String> installedNeoForge(Path instance)throws IOException {Map<String,String> versions=new LinkedHashMap<>();Path folder=instance.resolve("versions");if(!Files.isDirectory(folder))return versions;try(var ps=Files.walk(folder,2)){for(Path p:ps.filter(f->f.toString().endsWith(".json")).sorted().toList()){try{Map<String,Object> v=Json.object(Json.parse(Files.readString(p)));String nf="";for(Object library:Json.list(v.getOrDefault("libraries",List.of()))){String name=str(Json.object(library).get("name"));if(name.startsWith("net.neoforged:neoforge:"))nf=name.substring("net.neoforged:neoforge:".length());}if(nf.isBlank()){Matcher m=Pattern.compile("(?i)neoforge[- ]([0-9.]+)").matcher(str(v.get("id")));if(m.find())nf=m.group(1);}String mc=str(v.get("inheritsFrom"));if(mc.isBlank()&&v.get("arguments") instanceof Map<?,?> args){List<Object> game=Json.list(args.getOrDefault("game",null));for(int i=0;i+1<game.size();i++)if(str(game.get(i)).equals("--fml.mcVersion"))mc=str(game.get(i+1));}if(mc.isBlank()){Matcher m=Pattern.compile("^(1\\.[0-9]+(?:\\.[0-9]+)?)").matcher(str(v.get("id")));if(m.find())mc=m.group(1);}if(!nf.isBlank())versions.put(nf,mc);}catch(RuntimeException ignored){}}}return versions;}
 public static String loader(Path instance)throws IOException {
  Path cf=instance.resolve("minecraftinstance.json");if(Files.isRegularFile(cf)){Map<String,Object> m=Json.object(Json.parse(Files.readString(cf)));Object base=m.get("baseModLoader");if(base instanceof Map<?,?> bm){String name=str(bm.get("name"));Matcher match=Pattern.compile("(?i)neoforge[- ]([0-9.]+)").matcher(name);if(match.find())return match.group(1);String type=str(bm.get("type"));String version=str(bm.get("forgeVersion"));if(type.toLowerCase(Locale.ROOT).contains("neoforge")&&version.matches("[0-9.]+"))return version;}return "otro / no detectado";}
  Path prism=instance.resolve("mmc-pack.json");if(!Files.exists(prism)&&instance.getParent()!=null)prism=instance.getParent().resolve("mmc-pack.json");if(Files.isRegularFile(prism)){Map<String,Object> m=Json.object(Json.parse(Files.readString(prism)));for(Object x:Json.list(m.getOrDefault("components",List.of()))){Map<String,Object> c=Json.object(x);if(str(c.get("uid")).equals("net.neoforged"))return str(c.get("version"));}return "otro / no detectado";}
  Map<String,String> installed=installedNeoForge(instance);if(installed.containsKey("21.1.255"))return "21.1.255";if(installed.size()==1)return installed.keySet().iterator().next();return "no detectado";
 }
 private static String mcVersion(Path instance)throws IOException {Path cf=instance.resolve("minecraftinstance.json");if(Files.isRegularFile(cf)){Map<String,Object> m=Json.object(Json.parse(Files.readString(cf)));Object v=m.get("minecraftVersion");if(v instanceof String s)return s;if(v instanceof Map<?,?> vm)return str(vm.getOrDefault("name",null));Object base=m.get("baseModLoader");if(base instanceof Map<?,?> bm&&bm.get("minecraftVersion")!=null)return str(bm.get("minecraftVersion"));}Path p=instance.resolve("mmc-pack.json");if(!Files.exists(p)&&instance.getParent()!=null)p=instance.getParent().resolve("mmc-pack.json");if(Files.isRegularFile(p)){for(Object x:Json.list(Json.object(Json.parse(Files.readString(p))).getOrDefault("components",List.of()))){Map<String,Object> c=Json.object(x);if(str(c.get("uid")).equals("net.minecraft"))return str(c.get("version"));}}return installedNeoForge(instance).getOrDefault(loader(instance),"no detectado");}
 private static Map<String,String> parseIds(String text,String jarVersion){Map<String,String> ids=new LinkedHashMap<>();Matcher m=Pattern.compile("(?ms)^\\s*\\[\\[mods]][ \t]*(?:#[^\\n]*)?$(.*?)(?=^\\s*\\[|\\z)").matcher(text);while(m.find()){String block=m.group(1),id=toml(block,"modId"),version=toml(block,"version");if(!id.isBlank())ids.put(id,version.equals("${file.jarVersion}")?jarVersion:version);}return ids;}
 private static String toml(String text,String key){Matcher m=Pattern.compile("(?m)^\\s*"+Pattern.quote(key)+"\\s*=\\s*[\"']([^\"']+)[\"']").matcher(text);return m.find()?m.group(1):"";}
 private static Map<String,String> modIds(Path jar)throws IOException {Map<String,String> ids=new LinkedHashMap<>();try(ZipFile z=new ZipFile(jar.toFile())){String version="";ZipEntry manifest=z.getEntry("META-INF/MANIFEST.MF");if(manifest!=null)version=new java.util.jar.Manifest(z.getInputStream(manifest)).getMainAttributes().getValue("Implementation-Version");for(String name:List.of("META-INF/neoforge.mods.toml","META-INF/mods.toml")){ZipEntry e=z.getEntry(name);if(e!=null){ids.putAll(parseIds(new String(z.getInputStream(e).readAllBytes(),StandardCharsets.UTF_8),version==null?"":version));break;}}ZipEntry meta=z.getEntry("META-INF/jarjar/metadata.json");if(meta!=null){Map<String,Object> json=Json.object(Json.parse(new String(z.getInputStream(meta).readAllBytes(),StandardCharsets.UTF_8)));for(Object entry:Json.list(json.getOrDefault("jars",List.of()))){ZipEntry inner=z.getEntry(str(Json.object(entry).get("path")));if(inner==null)continue;try(ZipInputStream in=new ZipInputStream(z.getInputStream(inner))){ZipEntry e;while((e=in.getNextEntry())!=null)if(e.getName().equals("META-INF/neoforge.mods.toml")||e.getName().equals("META-INF/mods.toml"))mergeVersions(ids,parseIds(new String(in.readAllBytes(),StandardCharsets.UTF_8),""));}}}}return ids;}
 private static void mergeVersions(Map<String,String> target,Map<String,String> incoming){incoming.forEach((id,v)->target.merge(id,v,(a,b)->a.isBlank()?b:b.isBlank()?a:compare(a,b)>=0?a:b));}
 private static Map<String,String> primaryIds(Path jar)throws IOException{try(ZipFile z=new ZipFile(jar.toFile())){String v="";ZipEntry mf=z.getEntry("META-INF/MANIFEST.MF");if(mf!=null)v=Objects.toString(new java.util.jar.Manifest(z.getInputStream(mf)).getMainAttributes().getValue("Implementation-Version"),"");for(String n:List.of("META-INF/neoforge.mods.toml","META-INF/mods.toml")){ZipEntry e=z.getEntry(n);if(e!=null)return parseIds(new String(z.getInputStream(e).readAllBytes(),StandardCharsets.UTF_8),v);}return Map.of();}}
 private record Requirement(String id,String range){}
 private static List<Requirement> requirements(Path jar)throws IOException {List<Requirement> req=new ArrayList<>();try(ZipFile z=new ZipFile(jar.toFile())){ZipEntry e=z.getEntry("META-INF/neoforge.mods.toml");if(e==null)e=z.getEntry("META-INF/mods.toml");if(e==null)return req;String text=new String(z.getInputStream(e).readAllBytes(),StandardCharsets.UTF_8);Matcher blocks=Pattern.compile("(?ms)^\\s*\\[\\[dependencies\\.[^]]+]]\\s*$(.*?)(?=^\\s*\\[|\\z)").matcher(text);while(blocks.find()){String b=blocks.group(1);if((toml(b,"type").equals("required")||Pattern.compile("(?m)^\\s*mandatory\\s*=\\s*true").matcher(b).find())&&!toml(b,"side").equals("SERVER"))req.add(new Requirement(toml(b,"modId"),toml(b,"versionRange")));}}return req;}
 private static int compare(String a,String b){String[] x=a.split("[.+_-]"),y=b.split("[.+_-]");for(int i=0;i<Math.max(x.length,y.length);i++){String aa=i<x.length?x[i]:"0",bb=i<y.length?y[i]:"0";int c;if(aa.matches("\\d+")&&bb.matches("\\d+"))c=new java.math.BigInteger(aa).compareTo(new java.math.BigInteger(bb));else c=aa.compareToIgnoreCase(bb);if(c!=0)return c;}return 0;}
 public static boolean versionMatches(String actual,String range){if(range.isBlank()||range.equals("*"))return true;if(actual==null||actual.isBlank()||actual.startsWith("${"))return false;if(range.startsWith("[")&&range.endsWith("]")&&!range.contains(","))return compare(actual,range.substring(1,range.length()-1))==0;if((range.startsWith("[")||range.startsWith("("))&&(range.endsWith("]")||range.endsWith(")"))){String[] ends=range.substring(1,range.length()-1).split(",",-1);if(ends.length!=2)return false;return (ends[0].isBlank()||compare(actual,ends[0].strip())>(range.startsWith("[")?-1:0))&&(ends[1].isBlank()||compare(actual,ends[1].strip())<(range.endsWith("]")?1:0));}return compare(actual,range)>=0;}
 private static boolean archive(Path p)throws IOException {try(ZipFile central=new ZipFile(p.toFile());ZipInputStream in=new ZipInputStream(Files.newInputStream(p))){byte[] b=new byte[65536];ZipEntry e;while((e=in.getNextEntry())!=null){while(in.read(b)>=0){}}return true;}catch(ZipException e){return false;}}
 public static List<String> worlds(Path instance)throws IOException {Path saves=instance.resolve("saves");if(!Files.isDirectory(saves))return List.of();try(var stream=Files.list(saves)){return stream.filter(p->Files.isDirectory(p)&&Files.isRegularFile(p.resolve("level.dat"))).map(p->p.getFileName().toString()).sorted().toList();}}
 private static String fingerprint(Path instance)throws IOException {StringBuilder s=new StringBuilder();for(String name:List.of("minecraftinstance.json","mmc-pack.json","options.txt")){Path p=instance.resolve(name);if(Files.isRegularFile(p))s.append(name).append(sha(p));}Path mods=instance.resolve("mods");if(Files.isDirectory(mods)){try(var paths=Files.list(mods)){for(Path p:paths.filter(Files::isRegularFile).sorted().toList())s.append(p.getFileName()).append(Files.size(p)).append(Files.getLastModifiedTime(p));}}return s.toString();}
 public static Plan review(Pack pack,Path instance,List<String> selectedWorlds,Consumer<String> progress)throws IOException {
  if(!Files.isDirectory(instance))throw new IOException("Elige la carpeta de una instancia existente.");instance=instance.toAbsolutePath().normalize();List<Check> checks=new ArrayList<>();List<Copy> copies=new ArrayList<>();List<String> obsolete=new ArrayList<>();String nf=loader(instance),mc=mcVersion(instance);checks.add(new Check("NeoForge","NeoForge "+nf,"Se requiere exactamente "+pack.neoForge,nf.equals(pack.neoForge)));checks.add(new Check("Minecraft","Minecraft "+mc,"Se requiere "+pack.minecraft,mc.equals(pack.minecraft)));
  Map<String,String> bundledIds=new HashMap<>(),installedIds=new HashMap<>();Set<String> primaryBundled=new HashSet<>();Map<Path,Map<String,String>> installed=new LinkedHashMap<>();Path mods=instance.resolve("mods");if(Files.isDirectory(mods)){try(var ps=Files.list(mods)){for(Path p:ps.filter(p->p.toString().endsWith(".jar")).toList()){try{if(!archive(p))throw new IOException("JAR dañado");Map<String,String> ids=modIds(p);installed.put(p,ids);mergeVersions(installedIds,ids);}catch(IOException e){checks.add(new Check("Mods",p.getFileName().toString(),"JAR dañado; retíralo antes de instalar",false));}}}}
  for(Entry entry:pack.files){progress.accept(entry.path);Path source=under(pack.root,entry.path);boolean good=Files.isRegularFile(source)&&Files.size(source)==entry.size&&sha(source).equals(entry.sha256);if(good&&(entry.path.endsWith(".jar")||entry.path.endsWith(".zip")))good=archive(source);String group=entry.path.substring(0,entry.path.indexOf('/'));if(!good){checks.add(new Check(group,entry.path,"Falta, está dañado o no corresponde a esta versión",false));continue;}
   if(group.equals("mods")){Map<String,String> ids=modIds(source);for(String id:primaryIds(source).keySet())if(!primaryBundled.add(id))checks.add(new Check("Mods duplicados",id,"Hay dos versiones dentro del paquete; conserva solo una",false));mergeVersions(bundledIds,ids);}
   List<String> targets;if(group.equals("datapacks")){targets=new ArrayList<>();for(String world:selectedWorlds){if(!worlds(instance).contains(world))throw new IOException("Mundo no encontrado: "+world);targets.add("saves/"+safeName(world)+"/"+entry.path);}if(targets.isEmpty())checks.add(new Check(group,entry.path,"Pendiente: no se copiará hasta elegir un mundo. No bloquea los mods.",true));}else if(group.equals("shaderpacks")&&!installedIds.containsKey("iris")&&!installedIds.containsKey("oculus")&&!bundledIds.containsKey("iris")&&!bundledIds.containsKey("oculus")&&!pack.files.stream().anyMatch(f->f.path.startsWith("mods/")&&(f.path.toLowerCase(Locale.ROOT).contains("iris")||f.path.toLowerCase(Locale.ROOT).contains("oculus")))){targets=List.of();checks.add(new Check("Shaders",entry.path,"Omitido: no usas cargador de shaders. No bloquea la instalación.",true));}else targets=List.of(entry.path);
   for(String target:targets){Path dest=under(instance,target);boolean same=Files.isRegularFile(dest)&&sha(dest).equals(entry.sha256);checks.add(new Check(group,target,same?"Correcto · no se vuelve a copiar":Files.exists(dest)?"Actualizar · se guardará el original":"Instalar · archivo ausente",true));if(!same)copies.add(new Copy(source,target,entry.sha256));}
  }
  for(String category:ROOTS)if(pack.files.stream().noneMatch(f->f.path.startsWith(category+"/"))){Path folder=under(instance,category);long count=0;if(Files.isDirectory(folder))try(var ps=Files.list(folder)){count=ps.filter(Files::isRegularFile).count();}checks.add(new Check(category,"Carpeta "+category,count+" archivos existentes · este paquete no define versiones",true));}
  Set<String> allIds=new HashSet<>(installedIds.keySet());allIds.addAll(bundledIds.keySet());if(pack.files.stream().anyMatch(f->f.path.startsWith("shaderpacks/"))&&!allIds.contains("iris")&&!allIds.contains("oculus"))checks.add(new Check("Shaders","Cargador de shaders","Aviso: no se detectó Iris u Oculus. Se omiten los shaders; no bloquea los mods.",true));
  Map<String,String> versions=new HashMap<>(installedIds);versions.putAll(bundledIds);versions.put("minecraft",mc);versions.put("neoforge",nf);for(Entry f:pack.files)if(f.path.startsWith("mods/")&&Files.isRegularFile(under(pack.root,f.path)))for(Requirement requirement:requirements(under(pack.root,f.path))){String actual=versions.get(requirement.id);boolean valid=actual!=null&&versionMatches(actual,requirement.range);checks.add(new Check(valid?"Dependencias":"Aviso de dependencias",requirement.id+" requerido por "+Path.of(f.path).getFileName(),"Necesita "+requirement.range+". Encontrado: "+Objects.toString(actual,"no instalado")+". "+(valid?"Compatible.":actual==null?"Añade el JAR de "+requirement.id+" para NeoForge "+pack.minecraft+" y vuelve a revisar.":actual.isBlank()?"No se pudo leer su versión; revisa el JAR y su metadata.":"Sustituye la versión incompatible por una que cumpla este rango y vuelve a revisar.")+(valid?"":" Aviso orientativo: NeoForge realiza la validación definitiva al iniciar; no bloquea la copia."),true));}
  if(!pack.options.isEmpty())checks.add(new Check("Teclas","Perfil del pack",pack.options.size()+" ajustes · se aplicarán si activas la casilla",true));
  for(String id:pack.requiredMods)checks.add(new Check("Dependencias",id,allIds.contains(id)?"Disponible":"Falta este mod requerido en la instancia",allIds.contains(id)));
  Set<Path> keep=new HashSet<>();for(Entry f:pack.files)if(f.path.startsWith("mods/"))keep.add(under(instance,f.path));for(var e:installed.entrySet())if(!keep.contains(e.getKey())&&primaryIds(e.getKey()).keySet().stream().anyMatch(primaryBundled::contains)){String path=instance.relativize(e.getKey()).toString().replace('\\','/');obsolete.add(path);checks.add(new Check("Versiones antiguas",path,"Mover al respaldo para evitar duplicados",true));}
  if(pack.mode.equals("full")){Set<String> expected=new HashSet<>();for(Entry f:pack.files)if(f.path.startsWith("mods/"))expected.add(f.path);for(Path p:installed.keySet()){String rel=instance.relativize(p).toString().replace('\\','/');if(!expected.contains(rel)&&!obsolete.contains(rel))checks.add(new Check("Mods adicionales",rel,"No pertenece a este pack: retíralo o usa una instancia limpia",false));}}
  return new Plan(instance,pack,List.copyOf(checks),List.copyOf(copies),List.copyOf(obsolete),fingerprint(instance));
 }
 private static Map<String,String> options(Path p)throws IOException {Map<String,String> m=new LinkedHashMap<>();if(Files.exists(p))for(String line:Files.readAllLines(p)){int n=line.indexOf(':');if(n>0)m.put(line.substring(0,n),line.substring(n+1));}return m;}
 private static void atomicCopy(Path source,Path target)throws IOException {Files.createDirectories(target.getParent());Path temp=target.resolveSibling(target.getFileName()+".zi-temp-"+UUID.randomUUID());try{Files.copy(source,temp);try{Files.move(temp,target,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temp,target,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temp);}}
 public static Path install(Plan plan,boolean applyKeys,Consumer<String> progress)throws IOException {
  if(!plan.allowed())throw new IOException("Resuelve los avisos rojos antes de instalar.");if(!fingerprint(plan.instance).equals(plan.fingerprint))throw new IOException("La instancia cambió desde la revisión. Revísala de nuevo.");
  for(ProcessHandle p:ProcessHandle.allProcesses().toList()){String line=p.info().commandLine().orElse("").toLowerCase(Locale.ROOT);if(p.pid()!=ProcessHandle.current().pid()&&line.contains("--gamedir")&&line.contains(plan.instance.toString().toLowerCase(Locale.ROOT)))throw new IOException("Cierra Minecraft antes de instalar.");}
  Path control=under(plan.instance,".zomboid-installer"),backup=control.resolve("backups").resolve(System.currentTimeMillis()+"-"+UUID.randomUUID().toString().substring(0,8)),stage=control.resolve("staging").resolve(UUID.randomUUID().toString());Files.createDirectories(stage);List<Copy> writes=new ArrayList<>();List<Map<String,Object>> journal=new ArrayList<>();
  try{
   for(String category:ROOTS)if(!category.equals("datapacks"))Files.createDirectories(under(plan.instance,category));
   for(Copy copy:plan.copies){Path staged=under(stage,copy.relative);Files.createDirectories(staged.getParent());Files.copy(copy.source,staged);if(!sha(staged).equals(copy.sha))throw new IOException("Archivo del pack cambió: "+copy.relative);writes.add(new Copy(staged,copy.relative,copy.sha));}
   if(applyKeys&&!plan.pack.options.isEmpty()){Path current=under(plan.instance,"options.txt");Map<String,String> values=options(current);Map<String,String> desired=new LinkedHashMap<>(plan.pack.options);if(Files.exists(control.resolve("installed.json")))desired.remove("guiScale");else if(values.containsKey("guiScale")&&!values.get("guiScale").equals("0"))desired.remove("guiScale");values.putAll(desired);String text=String.join("\n",values.entrySet().stream().map(e->e.getKey()+":"+e.getValue()).toList())+"\n";Path staged=stage.resolve("options.txt");Files.writeString(staged,text);if(!Files.exists(current)||!sha(current).equals(sha(staged)))writes.add(new Copy(staged,"options.txt",sha(staged)));}
   if(writes.isEmpty()&&plan.obsolete.isEmpty()&&Files.isRegularFile(control.resolve("installed.json"))){Map<String,Object> previous=Json.object(Json.parse(Files.readString(control.resolve("installed.json"))));return under(control.resolve("backups"),str(previous.get("backup")));}
   Set<String> affected=new LinkedHashSet<>(plan.obsolete);writes.forEach(c->affected.add(c.relative));for(String rel:affected){Path old=under(plan.instance,rel);if(Files.exists(old)&&!Files.isRegularFile(old))throw new IOException("No es archivo: "+rel);Map<String,Object> item=new LinkedHashMap<>();item.put("path",rel);item.put("existed",Files.isRegularFile(old));if(Files.isRegularFile(old)){Path saved=under(backup,rel);Files.createDirectories(saved.getParent());Files.copy(old,saved);item.put("before",sha(saved));}Copy next=writes.stream().filter(c->c.relative.equals(rel)).findFirst().orElse(null);item.put("after",next==null?"":next.sha);journal.add(item);}
   Files.createDirectories(backup);Files.writeString(backup.resolve("receipt.json"),Json.write(Map.of("files",journal,"pack",plan.pack.name)));
   try{for(String rel:plan.obsolete){progress.accept("Respaldando "+rel);Files.deleteIfExists(under(plan.instance,rel));}for(Copy copy:writes){progress.accept("Instalando "+copy.relative);atomicCopy(copy.source,under(plan.instance,copy.relative));}Path marker=stage.resolve("installed-marker.json");Files.writeString(marker,Json.write(Map.of("pack",plan.pack.name,"backup",backup.getFileName().toString())));atomicCopy(marker,control.resolve("installed.json"));}catch(IOException|RuntimeException failure){try{restoreFiles(plan.instance,backup,journal,false);}catch(IOException rollback){failure.addSuppressed(rollback);}throw failure;}
   return backup;
  }finally{removeTree(stage);}
 }
 private static void restoreFiles(Path instance,Path backup,List<Map<String,Object>> journal,boolean check)throws IOException {if(check)for(var item:journal){Path current=under(instance,str(item.get("path")));String after=str(item.get("after"));if(after.isEmpty()?Files.exists(current):!Files.isRegularFile(current)||!sha(current).equals(after))throw new IOException("El archivo cambió después de instalar: "+item.get("path")+". No se sobrescribirá.");if(Boolean.TRUE.equals(item.get("existed"))&&!sha(under(backup,str(item.get("path")))).equals(str(item.get("before"))))throw new IOException("Respaldo dañado");}List<Map<String,Object>> reverse=new ArrayList<>(journal);Collections.reverse(reverse);for(var item:reverse){String rel=str(item.get("path"));Path current=under(instance,rel);if(Boolean.TRUE.equals(item.get("existed")))atomicCopy(under(backup,rel),current);else Files.deleteIfExists(current);}}
 public static void restoreLatest(Path instance)throws IOException {Path control=under(instance,".zomboid-installer"),marker=control.resolve("installed.json");if(!Files.exists(marker))throw new IOException("No hay una instalación para restaurar.");Map<String,Object> m=Json.object(Json.parse(Files.readString(marker)));Path backup=under(control.resolve("backups"),str(m.get("backup")));Map<String,Object> receipt=Json.object(Json.parse(Files.readString(backup.resolve("receipt.json"))));List<Map<String,Object>> list=Json.list(receipt.get("files")).stream().map(Json::object).toList();restoreFiles(instance,backup,list,true);Files.delete(marker);}
 public static void removeTree(Path path)throws IOException {if(!Files.exists(path))return;try(var stream=Files.walk(path)){for(Path p:stream.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}
 public static Path importZip(Path zip,Path workspace,String expectedMc,String expectedNf)throws IOException {Path root=workspace.resolve("pack-"+UUID.randomUUID());Files.createDirectories(root);long total=0;int count=0;try(ZipInputStream in=new ZipInputStream(Files.newInputStream(zip))){ZipEntry e;while((e=in.getNextEntry())!=null){if(e.isDirectory())continue;if(++count>30000)throw new IOException("Demasiados archivos en el ZIP");String name=safeName(e.getName());Path out=under(root,name);Files.createDirectories(out.getParent());try(OutputStream sink=Files.newOutputStream(out)){byte[] b=new byte[65536];int n;while((n=in.read(b))>=0){total+=n;if(total>16L*1024*1024*1024)throw new IOException("ZIP demasiado grande");sink.write(b,0,n);}}}}
  catch(Exception e){removeTree(root);throw e;}
  Path source=root;if(!Files.exists(source.resolve("pack.json"))&&!Files.isDirectory(source.resolve("mods"))){try(var paths=Files.walk(root,3)){source=paths.filter(p->Files.isDirectory(p.resolve("mods"))||Files.isRegularFile(p.resolve("pack.json"))).findFirst().orElse(root);}}
  if(Files.exists(source.resolve("pack.json"))){load(source);return source;}if(!Files.isDirectory(source.resolve("mods"))){removeTree(root);throw new IOException("Este ZIP no incluye los mods. Una exportación de CurseForge con solo manifest.json no sirve como pack sin descargar sus archivos.");}
  String actual=loader(source),mc=mcVersion(source);if(!actual.equals("no detectado")&&!actual.equals(expectedNf))throw new IOException("El ZIP usa NeoForge "+actual+", no "+expectedNf);if(!mc.equals("no detectado")&&!mc.equals(expectedMc))throw new IOException("El ZIP usa Minecraft "+mc);writeManifest(source,"ZOMBIES POLDO · completo","full",expectedMc,expectedNf,null);return source;
 }
 public static void writeManifest(Path root,String name,String mode,String mc,String nf,String world)throws IOException {List<Map<String,Object>> files=new ArrayList<>();for(String category:ROOTS){Path dir=root.resolve(category);if(Files.isDirectory(dir))try(var ps=Files.walk(dir)){for(Path p:ps.filter(Files::isRegularFile).sorted().toList()){String rel=root.relativize(p).toString().replace('\\','/');under(root,rel);files.add(Map.of("path",rel,"size",Files.size(p),"sha256",sha(p)));}}}Map<String,String> selected=new LinkedHashMap<>();options(root.resolve("options.txt")).forEach((k,v)->{if(k.startsWith("key_")||Set.of("guiScale","resourcePacks","incompatibleResourcePacks").contains(k))selected.put(k,v);});Files.writeString(root.resolve("pack.json"),Json.write(Map.of("formatVersion",1,"name",name,"mode",mode,"minecraft",mc,"neoForge",nf,"files",files,"options",selected)));}
 public static void exportInstance(Path instance,Path zip,String world,String mc,String nf,Consumer<String> progress)throws IOException {if(!loader(instance).equals(nf)||!mcVersion(instance).equals(mc))throw new IOException("La instancia de origen no tiene las versiones correctas.");Path temp=Files.createTempDirectory("zomboid-pack-export-");try{for(String category:ROOTS){Path dir=instance.resolve(category);if(Files.isDirectory(dir))try(var ps=Files.walk(dir)){for(Path p:ps.filter(Files::isRegularFile).toList()){String rel=instance.relativize(p).toString().replace('\\','/');Path out=under(temp,rel);under(instance,rel);Files.createDirectories(out.getParent());progress.accept(rel);Files.copy(p,out);}}}if(world!=null&&!world.isBlank()){if(!worlds(instance).contains(world))throw new IOException("Mundo inválido");Path dp=under(instance,"saves/"+world+"/datapacks");if(Files.isDirectory(dp))try(var ps=Files.walk(dp)){for(Path p:ps.filter(Files::isRegularFile).toList()){Path out=under(temp,"datapacks/"+dp.relativize(p).toString().replace('\\','/'));Files.createDirectories(out.getParent());if(Files.exists(out)&&!sha(out).equals(sha(p)))throw new IOException("Dos datapacks distintos tienen el mismo nombre");Files.copy(p,out,StandardCopyOption.REPLACE_EXISTING);}}}Path options=instance.resolve("options.txt");if(Files.exists(options))Files.copy(options,temp.resolve("options.txt"));writeManifest(temp,"ZOMBIES POLDO · completo","full",mc,nf,world);Files.deleteIfExists(temp.resolve("options.txt"));try(ZipOutputStream out=new ZipOutputStream(Files.newOutputStream(zip));var ps=Files.walk(temp)){for(Path p:ps.filter(Files::isRegularFile).toList()){out.putNextEntry(new ZipEntry(temp.relativize(p).toString().replace('\\','/')));Files.copy(p,out);out.closeEntry();}}}finally{removeTree(temp);}}
}
